//! Certora stand-in for `src/processor/mod.rs`, in force only for the
//! `unit_fee_collection` unit.
//!
//! It is declaration-for-declaration the developer's `processor/mod.rs`: the same eight
//! submodules, compiled from the very same source files (named here with `#[path]`
//! because this file sits elsewhere in the tree), and the same `pub use` re-exports.
//!
//! The one addition is `collect_fee`. The repository contains
//! `src/processor/collect_fee.rs` but never declares it, and the file carries no `use`
//! lines of its own, so it is mounted here as an inline module that supplies exactly the
//! five imports it needs and then textually includes the file, unmodified.

#[path = "../../processor/deposit.rs"]
pub mod deposit;
#[path = "../../processor/deposit_exact.rs"]
pub mod deposit_exact;
#[path = "../../processor/deposit_with_fee.rs"]
pub mod deposit_with_fee;
#[path = "../../processor/deposit_with_fee_exact.rs"]
pub mod deposit_with_fee_exact;
#[path = "../../processor/redeem_shares.rs"]
pub mod redeem_shares;
#[path = "../../processor/slash.rs"]
pub mod slash;
#[path = "../../processor/update_reward.rs"]
pub mod update_reward;

#[path = "../../processor/spl_token_utils.rs"]
pub mod spl_token_utils;

pub mod collect_fee {
    use crate::loaders::CollectFeeContext;
    use crate::operations::vault_collect_fee;
    use crate::processor::spl_token_utils::spl_transfer_assets_from_vault;
    use solana_program::account_info::AccountInfo;
    use solana_program::entrypoint::ProgramResult;

    include!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/src/processor/collect_fee.rs"
    ));
}

pub use collect_fee::*;
pub use deposit::*;
pub use deposit_exact::*;
